//! 🧪️ The actual scalar bridge agrees with the independent serde original budget representation.
use super::*;
#[test]
fn original_job_scalar_arguments_preserve_full_budget_without_heap(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let original:OriginalJobBudget=serde_json::from_value(corpus["budget"].clone()).unwrap();let expected:[u64;11]=serde_json::from_value(corpus["arguments"].clone()).unwrap();let((arguments,returned),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let arguments=original.scalar_arguments();(arguments,OriginalJobBudget::from_scalar_arguments(arguments).unwrap())});assert_eq!(arguments,expected);assert_eq!(returned,original);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(serde_json::to_value(returned).unwrap(),corpus["budget"]);for index in[0,1,2]{let mut foreign=expected;foreign[index]=0;assert!(OriginalJobBudget::from_scalar_arguments(foreign).is_err());}let mut invalid=expected;invalid[10]=2;assert!(OriginalJobBudget::from_scalar_arguments(invalid).is_err());let mut cancelled=expected;cancelled[10]=0;assert!(!OriginalJobBudget::from_scalar_arguments(cancelled).unwrap().cancelled);eprintln!("[DEBUG] Original scalar job input71/3/23 preserves all5grants, fuel17, absoluteus123456, cancellation; actual allocator0/0 and serde oracle agree");}
